  'audit.validationTitle': 'Validation audit AI',
  'audit.validationPrompt': "Voici la documentation du projet (dossier docs/). Suis le protocole strict de validation en 4 phases. NE PAS émettre KRONN:VALIDATION_COMPLETE tant que les 4 phases ne sont pas terminées.\n\n## Phase 1 — Auto-correction (autonome)\nLis le code source et corrige tout ce que tu peux : marqueurs TODO orphelins, fichiers squelettes, infos obsolètes. Mets à jour les fichiers docs/ directement.\n\n## Phase 2 — Questions d'ambiguïté (interactif)\nPose tes questions une par une. À chaque réponse, mets à jour les fichiers docs/ avant la question suivante. Si une réponse révèle de nouvelles zones d'ombre, pose des questions de suivi.\n\n## Phase 3 — Revue dette technique (interactif)\nPasse en revue CHAQUE entrée de docs/inconsistencies-tech-debt.md et docs/tech-debt/. Pour chaque item : est-ce correct ? Quelle priorité ? Faut-il créer un ticket ?\n\n## Phase 4 — Challenge documentation (interactif)\nPose-moi 2-3 questions pratiques qu'un dev rejoignant le projet poserait. Vérifie que la doc y répond. Si insuffisant, mets à jour et repose une question.\n\nUniquement quand les 4 phases sont terminées, termine par : \"KRONN:VALIDATION_COMPLETE\".",
