  'settings.recovery.title': 'Phrase de récupération',
  'settings.recovery.hint': 'Protège la clé qui chiffre vos secrets de plugins (tokens API). Choisissez une phrase ci-dessous : Kronn génère alors un code de récupération, affiché une seule fois, à conserver hors de cette machine (gestionnaire de mots de passe). Si la clé est un jour perdue (config écrasée, keychain réinitialisé, réinstallation), votre phrase — avec ce code si le dossier de données a aussi disparu — restaure l\'accès à vos secrets.',
  'settings.recovery.configured': 'Configurée',
  'settings.recovery.nudge': 'Aucune phrase de récupération configurée. Sans elle, une perte de la clé de chiffrement rend vos tokens de plugins définitivement irrécupérables — fortement recommandé.',
  'settings.recovery.setLabel': 'Choisissez une phrase de récupération',
  'settings.recovery.replaceLabel': 'Remplacer la phrase de récupération',
  'settings.recovery.passphrasePlaceholder': 'Min. 12 caractères — ex. « échouer.insérons.labeur »',
  'settings.recovery.confirmPlaceholder': 'Confirmez la phrase',
  'settings.recovery.tooShort': 'Au moins {0} caractères.',
  'settings.recovery.mnemonicTip': 'Astuce mémoire : les 3 mots what3words d\'un lieu que vous aimez font une excellente phrase, re-trouvable même sans sauvegarde — mais PAS votre domicile ni votre travail (devinables). Retenez lieu + langue du site + format exact (points, accents), et gardez quand même les mots dans votre gestionnaire.',
  'settings.recovery.mismatch': 'Les deux phrases ne correspondent pas.',
  'settings.recovery.setBtn': 'Créer le code de récupération',
  'settings.recovery.replaceBtn': 'Régénérer le code de récupération',
  'settings.recovery.saved': 'Phrase de récupération enregistrée.',
  'settings.recovery.saveCodeWarning': 'Sauvegardez ce code HORS de cette machine (gestionnaire de mots de passe, impression). Il ne sera plus jamais affiché. Sans lui + votre phrase, une clé perdue rend les secrets définitivement irrécupérables.',
  'settings.recovery.download': 'Télécharger',
  'settings.recovery.doneSaved': 'C\'est sauvegardé',
  'settings.recovery.codeCopied': 'Code de récupération copié.',
  'settings.recovery.copyFailed': 'Impossible de copier le code.',
  'mcp.recovery.restoreCta': 'Restaurer via la phrase de récupération',
