  'settings.bio': 'Bio',
  'settings.bioInfoTitle': 'À quels agents la bio est-elle transmise ?',
  'settings.bioInfoInjection': 'Kronn injecte la bio uniquement lorsqu’il lance lui-même l’agent d’une discussion, et seulement au premier échange. Cela inclut un agent CLI sélectionné comme agent de la discussion.',
  'settings.bioInfoCli': 'Elle n’est pas injectée dans un CLI utilisé directement ou ayant rejoint la discussion via MCP, ni dans les steps Agent d’un workflow. En mode full CLI, ce champ n’a donc aucun effet.',
  'settings.bioPlaceholder': 'Ex: Product Manager chez Acme Corp, spécialisé en analytics et growth...',
