  'settings.globalContext': 'Contexte global',
  'settings.globalContextInfoTitle': 'Quand ce contexte est-il injecté ?',
  'settings.globalContextInfoInjection': 'Contrairement à la bio, ce contexte accompagne chaque requête d’un agent de discussion lancé par Kronn, selon le mode d’injection choisi.',
  'settings.globalContextInfoCli': 'Il n’est pas injecté dans un CLI utilisé directement ou ayant rejoint la discussion via MCP, ni dans les steps Agent d’un workflow. En full CLI, ce champ n’a aucun effet.',
