  'settings.antiHallucSaved': 'Mode anti-hallucination enregistré',
  'settings.antiHallucHint': "Injecte une directive de sourçage aux agents lancés par Kronn et vérifie mécaniquement les sources citées ([src: fichier:ligne] / URL). « Avertir » signale sans bloquer ; « Strict » peut refuser une écriture lors des audits.",
  'settings.sourcingTitle': 'Sourcing & Anti-hallucination',
  'settings.betaBadge': 'Bêta',
  'settings.betaBadgeHint': 'Fonctionnalité en cours d\'évolution — comportement et réglages susceptibles de changer.',
  'settings.clTitle': 'Apprentissage continu',
  'settings.clDesc': 'Les agents peuvent proposer des conventions, préférences et pièges durables. Vous devez valider chaque proposition avant que Kronn l’écrive dans la documentation dédiée.',
  'settings.clToggleLabel': 'Activer l\'apprentissage continu',
  'settings.clHint': 'Une fois activé, l’outil MCP learning_propose est disponible et Kronn relie les projets compatibles à docs/learnings.md. La désactivation arrête les nouvelles propositions et retire ce lien, sans supprimer les apprentissages déjà validés.',
  'settings.clRiskTitle': 'Avertissement — fonctionnalité expérimentale',
  'settings.clRiskBody': 'L’activation modifie la documentation de vos projets : Kronn ajoute un bloc technique dans docs/AGENTS.md et crée ou complète docs/learnings.md après validation humaine. Cette mécanique est encore expérimentale. Activez-la de préférence sur des projets sauvegardés et versionnés ; la désactivation conserve le fichier d’apprentissages déjà créé.',
  'settings.clSaved': 'Apprentissage continu mis à jour.',
  'settings.clSaveError': 'Échec de la mise à jour de l\'apprentissage continu.',
  'settings.sourcingIntro': "Kronn encadre les affirmations des agents avec une convention de citation, puis signale les sources manquantes ou invalides. La portée exacte dépend de la manière dont l’agent est connecté à Kronn.",
  'settings.sourcingScopeTitle': 'Quels agents sont concernés ?',
  'settings.sourcingScopeLaunched': 'Les agents lancés par Kronn reçoivent la consigne de citer leurs sources, puis leurs réponses sont contrôlées.',
  'settings.sourcingScopeExternal': 'Un agent externe ayant rejoint une discussion via MCP ne reçoit pas forcément la consigne, mais les messages qu’il publie dans Kronn peuvent être contrôlés après coup. Un CLI utilisé entièrement hors de Kronn n’est pas concerné.',
  'settings.sourcingModeLabel': 'Mode de contrôle',
  'settings.sourcingSpecToggle': 'Voir la spec complète (Kronn AGENTS.md v1)',
  'settings.sourcingSpecHint': 'Convention technique appliquée par cette installation de Kronn.',
  'settings.sourcingSpecLoading': 'Chargement de la spec…',
  'settings.sourcingSpecError': "Impossible de charger la spec locale. Vérifiez que l'API Kronn est joignable.",
  'settings.ahExplainOff': 'aucune directive injectée, aucune analyse, aucune pastille. Les agents répondent sans contrainte de sourçage.',
  'settings.ahExplainWarn': "les agents lancés par Kronn reçoivent la consigne de citer leurs sources (`fichier:ligne`, URL ou « user-confirmed »). Kronn contrôle les citations accessibles et affiche une pastille lorsqu’une source manque ou paraît invalide. Rien n’est bloqué.",
  'settings.ahExplainEnforce': "refuse les citations `[src:]` fabriquées. À l'audit, le step est re-tenté (jusqu'à 3×) puis échoue proprement plutôt que d'écrire une doc à citations inventées ; en discussion, une réponse contenant une citation fabriquée est conservée mais signalée pour correction.",
  'settings.sourcingSpecRegion': 'Spec Kronn AGENTS.md v1',
  'settings.antiHallucSaveError': "Impossible d'enregistrer le mode anti-hallucination",
  'settings.ahEnforcePreviewToast': "« Strict » (beta) est actif : citations vérifiées à l'audit (retry) et signalées en discussion.",
