  'mcp.drift.never': '{0} appels sur `{1}` ont échoué ({2}), aucun n’a jamais abouti — cet endpoint n’existe probablement pas ou plus. Vérifie la spec du plugin.',
  'mcp.drift.sometimes': '{0} appels sur `{1}` ont échoué ({2}), mais d’autres aboutissent — l’endpoint existe, ce sont les paramètres déclarés qui ne correspondent pas.',
  'mcp.custom.helper.sys.verify': 'VÉRIFIE AVANT D’AFFIRMER — la doc d’une API ment souvent : noms de paramètres périmés, endpoints supprimés, pagination non documentée. Une spec inventée envoie les agents dans le mur pendant des heures. Si tu peux exécuter des commandes ET que l’utilisateur a fourni ses credentials, teste CHAQUE endpoint par un appel réel (curl) avant de le déclarer, et n’en déclare aucun que tu n’aies vu répondre. Trois pièges à contrôler : (1) un paramètre inconnu est souvent accepté et IGNORÉ en silence — un 200 ne prouve pas que le filtre a été appliqué, compare un champ discriminant de la réponse à ce que tu as demandé ; (2) note dans la description la FORME de la réponse quand elle est paginée ou enveloppée (`{data:[…], meta}`) et le nom exact des paramètres qui marchent ; (3) signale si une entrée est volumineuse, pour qu’un agent pense à projeter les champs utiles. Ce que tu n’as PAS pu vérifier, préfixe-le `❔ non vérifié :` dans sa description — ne l’affirme jamais.',
  'mcp.custom.helper.sys.style': "Reste concis. Pose une question à la fois si tu as besoin de clarifier. Précise toujours ce qui manque pour finaliser la config.",
  'mcp.custom.helper.sys.starter': "Salut ! Décris-moi l'API que tu veux configurer : colle un curl, un lien vers la doc, ou explique en langage naturel.",
