  'wiz.helpModeAdvanced': 'Plusieurs étapes en chaîne, conditions, déclencheurs programmés, batch.',
  'wiz.helpSimpleVsAdvanced': 'Simple = 1 étape, 1 agent, 1 tâche (ex: "génère un rapport hebdo"). Avancé = pipeline multi-étapes avec conditions (ex: "récupère les tickets → lance un batch → notifie"). Tu peux toujours passer en Avancé plus tard.',
  'wiz.task': 'Tâche',
  'wiz.agentLabel': 'Agent IA',
  'wiz.agentAndTierLabel': 'Agent et mode IA',
  'wiz.helpAgent': 'Le modèle IA qui va exécuter la tâche. Claude Code est généralement le plus capable ; Codex et Gemini sont des alternatives. Chaque agent doit être installé séparément sur ta machine.',
  'wiz.promptLabel': 'Que doit faire l\'agent ?',
  'wiz.helpPromptSimple': 'Décris la tâche en langage naturel, comme si tu demandais à un collègue. Tu peux utiliser des variables comme {{issue.title}} si le workflow est déclenché par une issue tracker.',
  'wiz.promptSimplePlaceholder': 'Décrivez la tâche en langage naturel...',
  'wiz.starterLabel': 'Ou démarrer depuis un exemple :',
  'wiz.helpStarters': 'Clique sur un exemple pour pré-remplir le nom et le prompt. Tu peux ensuite les modifier librement avant de valider.',
  'wiz.starter.codeReview': 'Revue de code',
  'wiz.starter.codeReviewPrompt': 'Analyse les derniers commits sur la branche principale. Pour chaque fichier modifié, identifie :\n- Les problèmes de qualité (code dupliqué, complexité excessive)\n- Les failles de sécurité potentielles\n- Les violations de conventions du projet\n\nGénère un rapport Markdown avec les problèmes classés par sévérité (critique / attention / suggestion).',
  'wiz.starter.changelog': 'Changelog automatique',
  'wiz.starter.changelogPrompt': 'Analyse tous les commits depuis le dernier tag de release. Pour chaque commit, identifie s\'il s\'agit d\'une nouvelle fonctionnalité, d\'un correctif, d\'une amélioration ou d\'un changement technique.\n\nGénère un changelog Markdown structuré avec les sections : Nouveautés, Correctifs, Améliorations, Technique.',
  'wiz.starter.techDebt': 'Détection dette technique',
  'wiz.starter.techDebtPrompt': 'Scanne le code source du projet et identifie les éléments de dette technique :\n- TODO/FIXME/HACK restants dans le code\n- Dépendances obsolètes ou avec vulnérabilités connues\n- Fichiers de plus de 500 lignes sans tests\n- Code mort ou imports inutilisés\n\nGénère un rapport priorisé avec l\'effort estimé (S/M/L) pour chaque élément.',
  'wiz.starter.testCoverage': 'Audit couverture tests',
  'wiz.starter.testCoveragePrompt': 'Analyse la structure du projet et identifie les fichiers et fonctions critiques qui n\'ont pas de tests :\n- Endpoints API sans test d\'intégration\n- Fonctions utilitaires sans test unitaire\n- Composants UI avec interactions sans test\n\nGénère une liste priorisée des tests manquants les plus importants à écrire, avec un squelette de test pour chacun.',
  'wiz.starter.docUpdate': 'Mise à jour documentation',
  'wiz.starter.docUpdatePrompt': 'Compare la documentation existante (README, docs/, commentaires) avec le code actuel. Identifie :\n- Les sections obsolètes ou incorrectes\n- Les nouvelles fonctionnalités non documentées\n- Les instructions d\'installation ou de configuration à mettre à jour\n\nPropose les corrections à apporter dans chaque fichier.',
  'wiz.starter.securityScan': 'Scan sécurité',
  'wiz.starter.securityScanPrompt': 'Effectue un audit de sécurité du projet :\n- Vérifie les dépendances pour les CVE connues\n- Cherche les secrets ou tokens hardcodés dans le code\n- Identifie les injections potentielles (SQL, XSS, command injection)\n- Vérifie les permissions et la configuration d\'authentification\n\nGénère un rapport avec les vulnérabilités classées par criticité (CRITICAL / HIGH / MEDIUM / LOW).',
